props:
leading={<>
        {headerOwnsDetail ? !formActive&&<Link scroll={false} className="mobile-back" href={backHref!} aria-label={backLabel}><Icon name="back"/></Link> : <>{hasListBack&&<Link scroll={false} className="mobile-back" href={backHref!} aria-label={backLabel}><Icon name="back"/></Link>}<h1 className="mobile-section-title"><LocalizedText verbatim={titleIsUserContent&&pathname!=="/dashboard"}>{mobileHeading}</LocalizedText></h1></>}
        {headerOwnsDetail&&<div className="mobile-header-context"><h1 className="mobile-header-title"><span><LocalizedText verbatim={titleIsUserContent}>{title}</LocalizedText></span></h1></div>}
      </>}

onClickCapture={event=>{
   const button=event.target instanceof Element?event.target.closest('button.button-primary'):null;
   // Prevent a step transition from acquiring native submit semantics in the same click.
   if(button&&guided&&step<labels.length-1)event.preventDefault();
   if(button&&(!guided||step===labels.length-1)&&!valid()){event.preventDefault();event.stopPropagation();}
  }}

leading={<>
        <DesktopNavigationToggle collapsed={navigationCollapsed} onToggle={toggleNavigation} controls="operator-desktop-navigation"/>
        {detail?<Link href={"/operator/"+key} className="mobile-back" aria-label="Zur Liste"><Icon name="back"/></Link>:key===""?<Link href="/operator" className="mobile-header-brand" aria-label="Zum Admin-Dashboard"><Logo compact/><span>One</span></Link>:<h1 className="operator-section-label"><LocalizedText>{title}</LocalizedText></h1>}
        <span className="operator-header-desktop-label"><LocalizedText>{"Admin"}</LocalizedText></span>
      </>}

actions={editable?<ActionsMenu label="Vertragsaktionen">
  {item.status==='draft'&&<ActionRow requiresWrite icon="edit" title="Vertragsentwurf bearbeiten" onClick={()=>setEditing(true)}/>}
  {['draft','paused'].includes(item.status)&&independent&&<ActionRow requiresWrite icon="check" title="Vertrag freigeben" disabled={!hasPublished||!query.data?.documentsReady} onClick={()=>rootCommand('active')}/>}
  {item.status==='active'&&<ActionRow requiresWrite icon="pause" title="Vertrag pausieren" onClick={()=>rootCommand('paused')}/>}
  {['active','paused'].includes(item.status)&&<ActionRow requiresWrite icon="close" title="Vertrag beenden" onClick={()=>rootCommand('ended')}/>}
  {['draft','active','paused'].includes(item.status)&&<ActionRow requiresWrite icon="close" title="Vertrag stornieren" onClick={()=>rootCommand('cancelled')}/>}
 </ActionsMenu>:undefined}
